#!/bin/sh -e
# Ported from the Python build of the oss-fuzz-theorems 2026.10 release (seeds/languages.tsv); do not edit.
#
# Builds the fuzz targets of idna into $OUT, each from the release's Python target for it (python/recipes.sh).
# compile runs build.sh with bash; the release ran each target's build with sh -e, and so does this.
[ -z "${BASH_VERSION:-}" ] || exec sh -e "$0"
. /usr/local/lib/oss-verify/release-target.sh

# fuzz_encode_decode: the release's target idna-fuzz_encode_decode
(
ov_target_begin idna-fuzz_encode_decode
PY_HARNESS=fuzz_encode_decode.py
PY_INSTALL="."
PY_ALLOW_MISSING=""
. /usr/local/lib/oss-verify/python/recipes.sh
build_lib() {
  oft_py_build
  oft_seal_getenv
  oft_seal_getpid
  oft_seal_mkstemp
}
LIB_ARCHIVE="lib/liboft.a"
LIB_CFLAGS=""
ov_target_build fuzz_encode_decode
)

# fuzz_idna_api: the release's target idna-fuzz_idna_api
(
ov_target_begin idna-fuzz_idna_api
PY_HARNESS=tests/fuzz_idna_api.py
PY_INSTALL="."
PY_ALLOW_MISSING=""
. /usr/local/lib/oss-verify/python/recipes.sh
build_lib() {
  oft_py_build
  oft_seal_getenv
  oft_seal_getpid
  oft_seal_mkstemp
}
LIB_ARCHIVE="lib/liboft.a"
LIB_CFLAGS=""
ov_target_build fuzz_idna_api
)

# fuzz_idna_codec: the release's target idna-fuzz_idna_codec
(
ov_target_begin idna-fuzz_idna_codec
PY_HARNESS=tests/fuzz_idna_codec.py
PY_INSTALL="."
PY_ALLOW_MISSING=""
. /usr/local/lib/oss-verify/python/recipes.sh
build_lib() {
  oft_py_build
  oft_seal_getenv
  oft_seal_getpid
  oft_seal_mkstemp
}
LIB_ARCHIVE="lib/liboft.a"
LIB_CFLAGS=""
ov_target_build fuzz_idna_codec
)
